insert into public.products(id,names,description,material,category_slug,base_price,image_url,source_image_url,source_url,is_new,is_children,is_active,sort_order) values ('d9dce5db1a','{"uk":"Наматрацник водонепроникний","ru":"Наматрасник  водонепроницаемый","en":"Mattress protector  Waterproof"}'::jsonb,'{"uk":"Махровий водостійкий наматрацник з бортами по периметру  має спеціальну водонепроникну мембрану, яка не пропускає вологу та залишає матрац сухим при будь-яких умовах. Наматрацник стійкий до плям, міцно сидить на самому матраці, не шуршить і не ковзає. Використовуючи даний наматрацник, Ваш сон буде комфортним та захищеним.","ru":"Махровий водостійкий наматрацник з бортами по периметру  має спеціальну водонепроникну мембрану, яка не пропускає вологу та залишає матрац сухим при будь-яких умовах. Наматрацник стійкий до плям, міцно сидить на самому матраці, не шуршить і не ковзає. Використовуючи даний наматрацник, Ваш сон буде комфортним та захищеним.","en":""}'::jsonb,'{"uk":"Махрова тканина. Водонепроникна мембрана та борти по периметру.","ru":"Махровая ткань. Водонепроницаемая мембрана и борта по периметру.","en":"Terry fabric. Waterproof membrane with fitted sides."}'::jsonb,'protectors',610.0,'assets/product-d9dce5db1a.webp','https://kari-san.ua/image/cache/catalog/1nm-220x150.jpg','https://kari-san.ua/namatrasniki-57/namatrasnik-nomer-1-1069/',false,false,true,61) on conflict(id) do update set names=excluded.names,description=excluded.description,material=excluded.material,category_slug=excluded.category_slug,base_price=excluded.base_price,image_url=excluded.image_url,source_image_url=excluded.source_image_url,source_url=excluded.source_url,is_new=excluded.is_new,is_children=excluded.is_children,sort_order=excluded.sort_order;
