insert into public.products(id,names,description,material,category_slug,base_price,image_url,source_image_url,source_url,is_new,is_children,is_active,sort_order) values ('eedb8ce411','{"uk":"Покривало Шарпей -01","ru":"Покривало Шарпей -01","en":"Покривало Шарпей -01"}'::jsonb,'{"uk":"Fleece - в перекладі з англійської означає обстрижену овечу або козячу шерсть. Чому штучний матеріал назвали саме так? Пледи з флісу стали сучасним символом домашнього затишку. На відміну від вовняних виробів, тканина нового покоління надзвичайно ніжна на дотик, гіпоалергенна, нагадує по своїй фактурі велюр. При цьому вона міцна, не стирається, зберігає колір, пишність волокон і форму навіть після численних прань.","ru":"Fleece - в перекладі з англійської означає обстрижену овечу або козячу шерсть. Чому штучний матеріал назвали саме так? Пледи з флісу стали сучасним символом домашнього затишку. На відміну від вовняних виробів, тканина нового покоління надзвичайно ніжна на дотик, гіпоалергенна, нагадує по своїй фактурі велюр. При цьому вона міцна, не стирається, зберігає колір, пишність волокон і форму навіть після численних прань.","en":""}'::jsonb,'{"uk":"Fleece - в перекладі з англійської означає обстрижену овечу або козячу шерсть. Чому штучний матеріал назвали саме так? Пледи з флісу стали сучасним символом домашнього затишку. На відміну від вовняних виробів, тканина нового покоління надзвичайно ніжна на дотик, гіпоалергенна, нагадує по своїй фактурі велюр. При цьому вона міцна, не стирається, зберігає колір, пишність волокон і форму навіть після численних прань.","ru":"Fleece - в перекладі з англійської означає обстрижену овечу або козячу шерсть. Чому штучний матеріал назвали саме так? Пледи з флісу стали сучасним символом домашнього затишку. На відміну від вовняних виробів, тканина нового покоління надзвичайно ніжна на дотик, гіпоалергенна, нагадує по своїй фактурі велюр. При цьому вона міцна, не стирається, зберігає колір, пишність волокон і форму навіть після численних прань.","en":"Fleece - в перекладі з англійської означає обстрижену овечу або козячу шерсть. Чому штучний матеріал назвали саме так? Пледи з флісу стали сучасним символом домашнього затишку. На відміну від вовняних виробів, тканина нового покоління надзвичайно ніжна на дотик, гіпоалергенна, нагадує по своїй фактурі велюр. При цьому вона міцна, не стирається, зберігає колір, пишність волокон і форму навіть після численних прань."}'::jsonb,'covers',528.0,'assets/product-eedb8ce411.webp','https://kari-san.ua/image/cache/catalog/5sh-220x150.jpg','https://kari-san.ua/pokryivala-17/pokryivalo-iz-flisa-nomer-3-655/',false,false,true,75) on conflict(id) do update set names=excluded.names,description=excluded.description,material=excluded.material,category_slug=excluded.category_slug,base_price=excluded.base_price,image_url=excluded.image_url,source_image_url=excluded.source_image_url,source_url=excluded.source_url,is_new=excluded.is_new,is_children=excluded.is_children,sort_order=excluded.sort_order;
